<template><div class="implementation-host"><header class="implementation-heading"><div><h1>Apoio Implantação</h1><p class="muted">Cadastro da obra, preparação de planilhas e revisão de laudos.</p></div><label>Conta atendida<select class="input" :value="accountId" @change="selectAccount"><option value="" disabled>Selecione uma conta</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{account.name}}</option></select></label></header><nav class="implementation-tabs" aria-label="Apoio Implantação"><RouterLink v-for="tab in tabs" :key="tab.path" :to="tab.path" class="btn" :class="{active:isActive(tab.path)}">{{tab.label}}</RouterLink></nav><nav v-if="route.path.startsWith('/planilhas')" class="implementation-tabs" aria-label="Ferramentas de planilhas"><RouterLink to="/planilhas/intake" class="btn">Pré-análise</RouterLink><RouterLink to="/planilhas/pre" class="btn">Conversão</RouterLink><RouterLink to="/planilhas/post" class="btn">Pós-importação</RouterLink></nav><p v-if="!accountId" role="status">Selecione a conta para iniciar o atendimento.</p><div id="implementation-overlays"></div><RouterView v-if="accountId" v-slot="{Component,route:current}"><KeepAlive><component :is="Component" :key="JSON.stringify([current.path,current.query.draft,current.query.process,current.query.revision])"/></KeepAlive></RouterView></div></template>
<script setup lang="ts">
import {useRoute} from 'vue-router';const props=defineProps<{accounts:Array<{id:string;name:string}>;accountId:string;onSelect:(id:string)=>void}>(),route=useRoute();
const tabs=[{path:'/',label:'Cadastro'},{path:'/planilhas/intake',label:'Planilhas'},{path:'/laudos',label:'Laudos'},{path:'/meus-rascunhos',label:'Rascunhos'},{path:'/admin/processos',label:'Processos'},{path:'/admin',label:'Revisão'},{path:'/emails',label:'E-mails'},{path:'/admin/ajuda',label:'Ajuda contextual'}];
function isActive(path:string){return path==='/planilhas/intake'?route.path.startsWith('/planilhas'):route.path===path;}function selectAccount(e:Event){const select=e.target as HTMLSelectElement,id=select.value;select.value=props.accountId;props.onSelect(id);}
</script>
